'use strict';

// Reverse-engineertes Systemair/Villavent CD-Panel-Protokoll (VR-700 DCV u.ä.)
// Laeuft ueber einen RS485<->WLAN-Adapter (z.B. Elfin EW11), der an den
// Bedienteil-Klemmen (12V/GND/Hi/Lo) angeschlossen ist. Der EW11 muss auf
// 57600 Baud, 8N1, "Protocol: None" (transparent) und "TCP Server" Port 502
// konfiguriert sein - NICHT auf "Modbus", das Geraet spricht kein Modbus.
//
// Frame-Format: 280 Byte, Header 0x55 0xAA, Byte[2] = Frame-Typ,
// letztes Byte = CRC-8 (Polynom 0x8D, init 0, keine Reflektion) ueber
// Byte[0..278].
//
// Byte 42  = Luefterstufe (0=Aus, 1=Niedrig, 2=Normal, 3=Hoch)
// Byte 95  = Temperaturstufe (0..5, sechsstufiger Handregler)
// Frame-Typ 0x0a = periodischer Zustands-Broadcast der Regelung
// Frame-Typ 0x01 = Panel-Kommando (folgt auf ein 0x02 der Regelung)

const HEADER = Buffer.from([0x55, 0xaa]);
const FRAME_LEN = 280;

function crc8(buf, poly = 0x8d) {
  let crc = 0;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let b = 0; b < 8; b++) {
      crc = (crc & 0x80) ? ((crc << 1) ^ poly) & 0xff : (crc << 1) & 0xff;
    }
  }
  return crc;
}

function verifyFrame(frame) {
  if (frame.length !== FRAME_LEN) return false;
  if (frame[0] !== 0x55 || frame[1] !== 0xaa) return false;
  return crc8(frame.subarray(0, FRAME_LEN - 1)) === frame[FRAME_LEN - 1];
}

// Zerlegt einen eingehenden Byte-Strom in vollstaendige, CRC-gueltige
// 280-Byte-Frames. Gibt {frames, rest} zurueck; `rest` ist der Puffer, der
// beim naechsten Aufruf vorangestellt werden muss.
//
// Wichtig: der Header-Bytewert 55 AA kann durch Zufall auch INNERHALB der
// Nutzdaten eines Frames auftreten. Ein naiver Split "zwischen zwei
// Vorkommen von 55 AA" erzeugt dadurch falsche Kurz-Frames. Deshalb wird
// hier an jeder Header-Position die CRC ueber die vollen 280 Byte geprueft;
// nur bei gueltiger CRC wird das Frame akzeptiert und um FRAME_LEN
// vorgerueckt. Bei ungueltiger CRC (falscher Positivtreffer) wird nur 1
// Byte vorgerueckt und die Suche nach dem naechsten Header fortgesetzt.
function splitFrames(buffer) {
  const frames = [];
  let offset = 0;

  while (true) {
    const idx = buffer.indexOf(HEADER, offset);
    if (idx === -1) {
      offset = buffer.length;
      break;
    }
    if (idx + FRAME_LEN > buffer.length) {
      offset = idx;
      break;
    }
    const candidate = buffer.subarray(idx, idx + FRAME_LEN);
    if (verifyFrame(candidate)) {
      frames.push(Buffer.from(candidate));
      offset = idx + FRAME_LEN;
    } else {
      offset = idx + 1;
    }
  }

  return { frames, rest: Buffer.from(buffer.subarray(offset)) };
}

function parseState(frame) {
  if (!verifyFrame(frame) || frame[2] !== 0x0a) return null;
  return {
    fanSpeed: frame[42],       // 0..3
    tempLevel: frame[95],      // 0..5
  };
}

// Bekannte, real aufgezeichnete Typ-0x01-Kommandoframes (gueltige CRC).
// Jedes Frame setzt EINEN der beiden Regler; der jeweils andere Wert im
// Frame spiegelt den Zustand zum Aufnahmezeitpunkt, wird aber von der
// Regelung offenbar nicht als Widerspruch gewertet - nur der eigentliche
// Zielwert (Byte 42 bzw. 95) wird uebernommen.
const FAN_SPEED_CMD = {
  0: '',
  1: '',
  2: '',
  3: '',
};

const TEMP_LEVEL_CMD = {
  0: '',
  1: '',
  2: '',
  3: '',
  4: '',
  5: '',
};

function commandForFanSpeed(level) {
  const hex = FAN_SPEED_CMD[level];
  if (!hex) throw new Error(`Unbekannte Luefterstufe: ${level}`);
  return Buffer.from(hex, 'hex');
}

function commandForTempLevel(level) {
  const hex = TEMP_LEVEL_CMD[level];
  if (!hex) throw new Error(`Unbekannte Temperaturstufe: ${level}`);
  return Buffer.from(hex, 'hex');
}

// !!! SICHERHEITSWARNUNG - NICHT VERWENDEN !!!
// commandForState() baut ein "Frankenstein"-Frame aus einem kompletten
// TEMP-Template (280 Byte, von denen die meisten Felder NIE entschluesselt
// wurden) mit nur 4 ueberschriebenen Fan-Bytes. Der Einsatz dieser Funktion
// hat auf der echten Anlage (VR-700) zu einem Absturz/Reset der
// Regelungsplatine gefuehrt (Panel und EW11 gleichzeitig ohne Strom -
// die Hauptplatine selbst ist neu gestartet). Vermutung: eine interne
// Konsistenzpruefung zwischen unbekannten Feldern wurde durch das Mischen
// zweier verschiedener Snapshots verletzt. Nur commandForFanSpeed() und
// commandForTempLevel() (exakte, unveraenderte aufgezeichnete Frames) sind
// nachweislich sicher und sollen verwendet werden. Diese Funktion bleibt nur
// zu Dokumentationszwecken stehen - vor jeder Reaktivierung braucht es
// zwingend eine gruendlichere Protokoll-Analyse der bislang unbekannten
// Frame-Felder, idealerweise mit einem physisch erreichbaren Testgeraet.
function commandForState(fanLevel, tempLevel) {
  const baseHex = TEMP_LEVEL_CMD[tempLevel] ?? TEMP_LEVEL_CMD[0];
  const frame = Buffer.from(baseHex, 'hex');
  frame[42] = fanLevel;
  frame[24] = FAN_PCT[fanLevel] ?? 0;
  frame[25] = FAN_PCT[fanLevel] ?? 0;
  frame[100] = FAN_B100[fanLevel] ?? 0;
  frame[279] = crc8(frame.subarray(0, FRAME_LEN - 1));
  return frame;
}

module.exports = {
  HEADER,
  FRAME_LEN,
  crc8,
  verifyFrame,
  splitFrames,
  parseState,
  commandForFanSpeed,
  commandForTempLevel,
  commandForState,
};
